import { expect, test } from 'bun:test';
import { feedLedger, parseRollout } from '../src/rollout-reader';
import { UsageLedger } from '../src/usage-ledger';

function jsonl(...payloads: Record<string, unknown>[]): string {
  return payloads.map(payload => JSON.stringify({ type: 'response_item', payload })).join('\n');
}

test('messages without IDs retain every occurrence, including repeated text', () => {
  const rollout = parseRollout(jsonl(
    { type: 'message', role: 'user', content: 'Run the scanner tests before committing' },
    { type: 'message', role: 'assistant', content: [{ text: 'Running tests now.' }] },
    { type: 'message', role: 'user', content: 'Run the scanner tests before committing' },
    { type: 'message', role: 'assistant', content: 'Tests passed.' },
  ));
  expect(rollout.events).toEqual([
    { kind: 'user_message', id: '', text: 'Run the scanner tests before committing' },
    { kind: 'assistant_message', id: '', text: 'Running tests now.' },
    { kind: 'user_message', id: '', text: 'Run the scanner tests before committing' },
    { kind: 'assistant_message', id: '', text: 'Tests passed.' },
  ]);
  const ledger = new UsageLedger();
  feedLedger(ledger, rollout);
  expect(ledger.countsFor('run the scanner tests before committing')?.userRepeats).toBe(2);
});

for (const type of ['function_call', 'custom_tool_call']) {
  test(`${type} without IDs deduplicates by call_id separately from outputs`, () => {
    const call = { type, call_id: 'call-1', name: 'run_tests', arguments: '{"path":"test/"}' };
    const output = { type: `${type}_output`, call_id: 'call-1', output: 'passed' };
    const rollout = parseRollout(jsonl(call, output, call, output,
      { ...call, call_id: 'call-2' }, { ...output, call_id: 'call-2' }));
    expect(rollout.events).toEqual([
      { kind: 'tool_call', id: '', callId: 'call-1', name: 'run_tests', args: { path: 'test/' } },
      { kind: 'tool_output', id: '', callId: 'call-1', text: 'passed' },
      { kind: 'tool_call', id: '', callId: 'call-2', name: 'run_tests', args: { path: 'test/' } },
      { kind: 'tool_output', id: '', callId: 'call-2', text: 'passed' },
    ]);
  });
}

test('tool items with neither item IDs nor call IDs retain each occurrence', () => {
  const call = { type: 'function_call', name: 'run_tests', arguments: '{}' };
  const output = { type: 'function_call_output', output: 'passed' };
  expect(parseRollout(jsonl(call, output, call, output)).events.map(event => event.kind))
    .toEqual(['tool_call', 'tool_output', 'tool_call', 'tool_output']);
});

test('explicit IDs take precedence and cannot collide with fallback tool identities', () => {
  const call = { type: 'function_call', call_id: 'shared', name: 'run_tests', arguments: '{}' };
  const output = { type: 'function_call_output', call_id: 'shared', output: 'passed' };
  const message = { type: 'message', role: 'user', id: 'tool_call:shared', content: 'Keep me' };
  const rollout = parseRollout(jsonl(
    message, message, call, call, output, output,
    { ...call, id: 'explicit-1' }, { ...call, id: 'explicit-1', call_id: 'changed' },
    { ...call, id: 'explicit-2' },
  ) + '\n{"type":"response_item","payload":');
  expect(rollout.events.map(event => [event.kind, event.id])).toEqual([
    ['user_message', 'tool_call:shared'], ['tool_call', ''], ['tool_output', ''],
    ['tool_call', 'explicit-1'], ['tool_call', 'explicit-2'],
  ]);
});
